config.script:
series_names = ['CLG', 'DFT', 'IDLE', 'STOP', 'FLT']
areas = []
try:
	areas = list(self.view.custom.metrics.sectionNames or [])
except:
	areas = []
si = -1
di = -1
try:
	si = int(event.seriesIndex)
except:
	try:
		si = int(event['seriesIndex'])
	except:
		si = -1
try:
	di = int(event.dataPointIndex)
except:
	try:
		di = int(event['dataPointIndex'])
	except:
		di = -1
if si < 0 or si >= len(series_names) or di < 0 or di >= len(areas):
	return
system.perspective.sendMessage(
	'UtilityOverviewHighlight',
	{
		'action': 'selectAreaStatus',
		'area': str(areas[di]),
		'status': series_names[si],
		'cg': '',
	},
	scope='page'
)

transforms.code:
tagPath = ''
try:
	tagPath = str(self.view.params.tagPath or '')
except:
	pass
view_name = self.view.id.split('@')[0]
items = []
if value:
	logged = tagPath if tagPath.strip() else 'No TagPath: ' + view_name.split('/')[-1]
	items.append({
		"text": 'Ticket Logger',
		"icon": {"path": 'material/info', "color": "--neutral-80", "style": {}},
		"style": {"classes": "bg-component Fonts/Value", "height": 24, "width": 170},
		"type": "message",
		"children": [],
		"link": {"url": "", "target": "self"},
		"method": {"name": "", "params": {}},
		"message": {"type": 'ticketLog', "payload": {'tagPath': logged, 'viewName': view_name, 'sender': self.view.id}, "scope": 'page'}
	})
return items
